CREATE TABLE `Message` (
  `id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `fromUserId` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `toUserId` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bolaoId` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `subject` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `body` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` enum('ENVIADA','LIDA','RESPONDIDA') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ENVIADA',
  `parentId` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  KEY `Message_toUserId_status_idx` (`toUserId`,`status`),
  KEY `Message_fromUserId_idx` (`fromUserId`),
  KEY `Message_bolaoId_idx` (`bolaoId`),
  KEY `Message_parentId_fkey` (`parentId`),
  CONSTRAINT `Message_bolaoId_fkey` FOREIGN KEY (`bolaoId`) REFERENCES `Bolao` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `Message_fromUserId_fkey` FOREIGN KEY (`fromUserId`) REFERENCES `User` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `Message_parentId_fkey` FOREIGN KEY (`parentId`) REFERENCES `Message` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `Message_toUserId_fkey` FOREIGN KEY (`toUserId`) REFERENCES `User` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
